/*
 * buzzer.h - Piezo buzzer on PTA1, tone generated by PIT channel 1
 */
#ifndef BUZZER_H
#define BUZZER_H

#include <stdint.h>

void buzzer_init(void);             /* call after timer_init() (PIT clock must be on) */
void buzzer_tone(uint16_t freqHz);  /* square wave at freqHz, 0 = silence             */
void buzzer_on(void);               /* plain ON (DC level, no PIT)                    */
void buzzer_off(void);              /* silence                                        */

#endif /* BUZZER_H */
